PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// ConvTranspose3d specialized for:
//   kernel = 3x3x3, stride = 1, padding = 0, output_padding = 0,
//   dilation = 1, groups = 1, dtype = float32
//   in  : (N, 48, 96, 96, 96)  contiguous
//   w   : (48, 24, 3, 3, 3)    contiguous  (in_ch, out_ch, kD, kH, kW)
//   bias: (24,) or dummy
//   out : (N, 24, 98, 98, 98)  contiguous
// out[b,oc,z,y,x] = sum_{ic,kz,ky,kx} w[ic,oc,2-kz,2-ky,2-kx]
//                   * in[b,ic,z+kz-2,y+ky-2,x+kx-2]   (zero outside input)
//                 + bias[oc] (optional)
//
// Structural rewrite: thread-level register blocking over output channels.
// Each thread computes ALL 24 output channels for one (b,z,y,x) site and
// keeps 24 accumulators in registers.  Every input value fetched from
// global memory is reused for 24 FMAs (one per output channel), cutting
// global input traffic ~24x and amortizing tap/address overhead over
// 24 FMAs instead of 1.
.visible .entry conv_transpose3d_k3_s1(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total,
    .param .u32 has_bias
)
{
    .reg .pred  %p<8>;
    .reg .b32   %r<40>;
    .reg .b64   %rd<20>;
    .reg .f32   %f<32>;
    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r0,  [total];
    ld.param.u32 %r1,  [has_bias];
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.u32 %r5, %r2, %r3, %r4;          // idx = global (b,z,y,x) spatial index
    setp.ge.u32 %p0, %r5, %r0;
    @%p0 bra DONE;                          // partial-block bounds check
    // decode idx -> b(r10), z(r12), y(r13), x(r14)
    rem.u32 %r14, %r5, 98;
    div.u32 %r6,  %r5, 98;
    rem.u32 %r13, %r6, 98;
    div.u32 %r6,  %r6, 98;
    rem.u32 %r12, %r6, 98;
    div.u32 %r10, %r6, 98;
    // sp(r33) = spatial offset inside the batch = idx - b*941192
    mul.lo.u32 %r34, %r10, 941192;
    sub.u32 %r33, %r5, %r34;
    // tap bounds: klo = max(0, 2 - coord), khi = min(2, 97 - coord)
    mov.s32 %r15, 2;
    sub.s32 %r15, %r15, %r12;
    max.s32 %r15, %r15, 0;                  // kz_lo
    mov.s32 %r16, 97;
    sub.s32 %r16, %r16, %r12;
    min.s32 %r16, %r16, 2;                  // kz_hi
    mov.s32 %r17, 2;
    sub.s32 %r17, %r17, %r13;
    max.s32 %r17, %r17, 0;                  // ky_lo
    mov.s32 %r18, 97;
    sub.s32 %r18, %r18, %r13;
    min.s32 %r18, %r18, 2;                  // ky_hi
    mov.s32 %r19, 2;
    sub.s32 %r19, %r19, %r14;
    max.s32 %r19, %r19, 0;                  // kx_lo
    mov.s32 %r20, 97;
    sub.s32 %r20, %r20, %r14;
    min.s32 %r20, %r20, 2;                  // kx_hi
    // 24 output-channel accumulators f0..f23
    mov.f32 %f0,  0f00000000;
    mov.f32 %f1,  0f00000000;
    mov.f32 %f2,  0f00000000;
    mov.f32 %f3,  0f00000000;
    mov.f32 %f4,  0f00000000;
    mov.f32 %f5,  0f00000000;
    mov.f32 %f6,  0f00000000;
    mov.f32 %f7,  0f00000000;
    mov.f32 %f8,  0f00000000;
    mov.f32 %f9,  0f00000000;
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    mov.f32 %f17, 0f00000000;
    mov.f32 %f18, 0f00000000;
    mov.f32 %f19, 0f00000000;
    mov.f32 %f20, 0f00000000;
    mov.f32 %f21, 0f00000000;
    mov.f32 %f22, 0f00000000;
    mov.f32 %f23, 0f00000000;
    mov.u32 %r21, 0;                        // ic = 0
IC_LOOP:
    setp.ge.u32 %p1, %r21, 48;
    @%p1 bra IC_DONE;
    // rd4 = in + (b*48 + ic) * 884736 * 4   (input plane base)
    mad.lo.u32 %r22, %r10, 48, %r21;
    mul.lo.u32 %r22, %r22, 884736;
    mul.wide.u32 %rd5, %r22, 4;
    add.s64 %rd4, %rd0, %rd5;
