    @%p2 bra KZ_DONE;
    add.s32 %r25, %r12, %r24;
    sub.s32 %r25, %r25, 2;                  // iz = z + kz - 2
    mul.lo.u32 %r26, %r25, 36864;           // iz * 96 * 96 * 4 (bytes)
    cvt.u64.u32 %rd8, %r26;
    add.s64 %rd9, %rd4, %rd8;               // input slice base
    mov.s32 %r27, %r17;                     // ky = ky_lo
KY_LOOP:
    setp.gt.s32 %p3, %r27, %r18;
    @%p3 bra KY_DONE;
    add.s32 %r28, %r13, %r27;
    sub.s32 %r28, %r28, 2;                  // iy = y + ky - 2
    // rd11 = slice + (iy*96 + x + kx_lo - 2) * 4
    mad.lo.u32 %r29, %r28, 96, %r14;
    add.s32 %r29, %r29, %r19;
    sub.s32 %r29, %r29, 2;
    mul.lo.u32 %r29, %r29, 4;
    cvt.u64.u32 %rd10, %r29;
    add.s64 %rd11, %rd9, %rd10;
    // flipped weight tap base for kx_lo: t = 26 - (kz*9 + ky*3 + kx_lo)
    mul.lo.u32 %r30, %r24, 9;
    mad.lo.u32 %r30, %r27, 3, %r30;
    add.s32 %r30, %r30, %r19;
    mov.u32 %r32, 26;
    sub.s32 %r30, %r32, %r30;
    mul.lo.u32 %r30, %r30, 4;
    cvt.u64.u32 %rd12, %r30;
    add.s64 %rd13, %rd6, %rd12;             // w tap ptr; oc stride = 27*4 = 108 B
    mov.s32 %r31, %r19;                     // kx = kx_lo
KX_LOOP:
    setp.gt.s32 %p4, %r31, %r20;
    @%p4 bra KX_DONE;
    ld.global.f32 %f24, [%rd11];            // input value reused for all 24 oc
    ld.global.f32 %f25, [%rd13];
    fma.rn.f32 %f0,  %f24, %f25, %f0;
    ld.global.f32 %f25, [%rd13+108];
    fma.rn.f32 %f1,  %f24, %f25, %f1;
    ld.global.f32 %f25, [%rd13+216];
    fma.rn.f32 %f2,  %f24, %f25, %f2;
    ld.global.f32 %f25, [%rd13+324];
    fma.rn.f32 %f3,  %f24, %f25, %f3;
    ld.global.f32 %f25, [%rd13+432];
    fma.rn.f32 %f4,  %f24, %f25, %f4;
    ld.global.f32 %f25, [%rd13+540];
    fma.rn.f32 %f5,  %f24, %f25, %f5;
    ld.global.f32 %f25, [%rd13+648];
    fma.rn.f32 %f6,  %f24, %f25, %f6;
    ld.global.f32 %f25, [%rd13+756];
    fma.rn.f32 %f7,  %f24, %f25, %f7;
    ld.global.f32 %f25, [%rd13+864];
    fma.rn.f32 %f8,  %f24, %f25, %f8;
    ld.global.f32 %f25, [%rd13+972];
    fma.rn.f32 %f9,  %f24, %f25, %f9;
    ld.global.f32 %f25, [%rd13+1080];
    fma.rn.f32 %f10, %f24, %f25, %f10;
    ld.global.f32 %f25, [%rd13+1188];
    fma.rn.f32 %f11, %f24, %f25, %f11;
    ld.global.f32 %f25, [%rd13+1296];
    fma.rn.f32 %f12, %f24, %f25, %f12;
    ld.global.f32 %f25, [%rd13+1404];
    fma.rn.f32 %f13, %f24, %f25, %f13;
    ld.global.f32 %f25, [%rd13+1512];
    fma.rn.f32 %f14, %f24, %f25, %f14;
    ld.global.f32 %f25, [%rd13+1620];
    fma.rn.f32 %f15, %f24, %f25, %f15;
    ld.global.f32 %f25, [%rd13+1728];
    fma.rn.f32 %f16, %f24, %f25, %f16;
    ld.global.f32 %f25, [%rd13+1836];
    fma.rn.f32 %f17, %f24, %f25, %f17;
    ld.global.f32 %f25, [%rd13+1944];
    fma.rn.f32 %f18, %f24, %f25, %f18;
    ld.global.f32 %f25, [%rd13+2052];
    fma.rn.f32 %f19, %f24, %f25, %f19;
    ld.global.f32 %f25, [%rd13+2160];
    fma.rn.f32 %f20, %f24, %f25, %f20;
    ld.global.f32 %f25, [%rd13+2268];
    fma.rn.f32 %f21, %f24, %f25, %f21;
    ld.global.f32 %f25, [%rd13+2376];
    fma.rn.f32 %f22, %f24, %f25, %f22;
    ld.global.f32 %f25, [%rd13+2484];
    fma.rn.f32 %f23, %f24, %f25, %f23;
    add.s64 %rd11, %rd11, 4;                // next input column
    sub.s64 %rd13, %rd13, 4;                // previous (flipped) weight tap
    add.s32 %r31, %r31, 1;
    bra KX_LOOP;
