    add.s32 %r27, %r27, 1;
    bra KY_LOOP;
KY_DONE:
    add.s32 %r24, %r24, 1;
    bra KZ_LOOP;
KZ_DONE:
    add.s32 %r21, %r21, 1;
    bra IC_LOOP;
